\begin{proof}
There are two cases depending on the relative values of $\gamma$ and $\lambda$. 

First, suppose $\left(1+\frac{5}{\log n}\right)\gamma \ge \lambda$. Then,
\[q^{-\lambda} \le q^{-\gamma(1+ 5/\log n)} =  2^{1+5/\log n} \le 2\left(1+O\left(\frac{1}{\log n}\right)\right) = 2 + O\left(\frac{1}{\log n}\right).\]
By \Cref{lem:karger-relvar},  when $p^\lambda \le n^{-0.5}$, the relative second moment of $z_H(p/q)$ is upper bounded by $q^{-\lambda}\left(1+O\left(\frac{1}{\log n}\right)\right)$, which is at most $2+O\left(\frac{1}{\log n}\right)$ by our bound on $q^{-\lambda}$ above.

In the rest of the proof, we assume $\left(1+\frac{5}{\log n}\right)\gamma < \lambda$. This proof now follows the same template as in Karger's analysis~\cite{Karger20}. The main difference is that we use the parameter $\gamma$ whereas Karger uses $\lambda$. 

The relative second moment is bounded as:
\begin{align*}
\frac{\E[z_H(p/q)^2]}{(\zgp)^2}
&= \frac{1}{(\zgp)^2}\cdot \E\bigg[\sum_{C_i, C_j \in \mathcal{C}(H)}\left(\frac{p}{q}\right)^{c_i+c_j}\bigg] 
= \frac{1}{(\zgp)^2}\sum_{C_i, C_j\in \mathcal{C}(G)} q^{|C_i\cup C_j|}\cdot \left(\frac{p}{q}\right)^{c_i+c_j}\\
&= \frac{1}{(\zgp)^2}\left(\sum_{C_i}\frac{p^{2c_i}}{q^{c_i}} + \sum_{C_i\ne C_j: |C_i\cap C_j|\le \gamma} \frac{p^{c_i+c_j}}{q^{|C_i\cap C_j|}} + \sum_{C_i\ne C_j: |C_i\cap C_j| > \gamma} \frac{p^{c_i+c_j}}{q^{|C_i\cap C_j|}}\right).
\end{align*}
In the above expression, we distinguished between the cases $C_i = C_j$ and $C_i \ne C_j$, and the second case is further split into $|C_i \cap C_j| \le \gamma$ and $|C_i\cap C_j| > \gamma$. We define:
\begin{align*}
    V_1 &= \sum_{C_i}\frac{p^{2c_i}}{q^{c_i}}\\
    V_2 &= \sum_{C_i\ne C_j: |C_i\cap C_j|\le \gamma} \frac{p^{c_i+c_j}}{q^{|C_i\cap C_j|}}\\
    V_3 &= \sum_{C_i\ne C_j: |C_i\cap C_j| > \gamma} \frac{p^{c_i+c_j}}{q^{|C_i\cap C_j|}}.
\end{align*}

We first bound $V_1$:

\[
V_1 - 2\sum_{C_i} p^{2c_i}
= \sum_{C_i} p^{2c_i}\left(\frac{1}{q^{c_i}} - \frac{1}{q^\gamma}\right)
= \frac{p^\gamma}{q^\gamma} \sum_{C_i} p^{c_i} \cdot p^{c_i-\gamma}(q^{-(c_i-\gamma)}-1)
= 2\cdot p^\gamma \sum_{C_i} p^{c_i} \cdot p^{c_i-\gamma}(q^{-(c_i-\gamma)}-1)
\]

Let us also denote $t_i=\frac{c_i-\gamma}{\gamma}$ and $f(t_i) = (2u)^{t_i} - u^{t_i} = p^{c_i-\gamma}(q^{-(c_i-\gamma)}-1)$ where $u=p^\gamma$. Therefore, 
\[
    V_1 - 2\sum_{C_i} p^{2c_i} = 2 p^{\gamma} \sum_{C_i} p^{c_i}\cdot f(t_i).
\]
Note that since $p^{\lambda}\in [n^{-3}, n^{-0.5}]$ and $\gamma\in[\frac 34 \lambda, \lambda]$, we have $u=p^{\gamma}\in [n^{-3}, n^{-0.375}]$. We now use the following fact, which we prove in the appendix:

\begin{fact}\label{fact:dfdt}
For function $f(t) = (2u)^t - u^t$, suppose $u \le n^{-0.375}$ and $t\ge\frac{5}{\log n}$. Then, for $n$ larger than some constant, we have $\frac{\diff f}{\diff t} < 0$.
\end{fact}

Thus, $f$ is monotone decreasing when $t\ge\frac{5}{\log n}$. Since $t_i \ge \frac{\lambda-\gamma}{\gamma}\ge \frac{5}{\log n}$, we can upper bound $f(t_i)\le f\left(\frac{5}{\log n}\right) = u^{5/\log n}\cdot (2^{5/\log n}-1)$. Combined with $p^\gamma \le \zgp$ by \Cref{lem:gamma-z-bound}, we have
\begin{align*}
    V_1 - 2\sum_{C_i}p^{2c_i}
    &\le 2 \cdot p^\gamma \cdot\zgp\cdot f\left(\frac{5}{\log n}\right)
    \le  2\cdot (\zgp)^2 \cdot u^{5/\log n} \cdot (2^{5 / \log n}-1)\\
    &\le 2(\zgp)^2 \left(n^{-0.375}\right)^{5/\log n} \cdot (2^{5/\log n}-1)
    \le O\left(\frac{1}{\log n}\right)\cdot (\zgp)^2.
\end{align*}
Thus,
\begin{align}\label{eq:v1}
    V_1 \le O\left(\frac{1}{\log n}\right)\cdot (\zgp)^2 + 2\sum_{C_i}p^{2c_i}.
\end{align}

Next, we bound $V_2$ as follows:
\begin{align}\label{eq:v2}
V_2 
= \sum_{C_i\ne C_j, |C_i\cap C_j|\le \gamma} \frac{p^{c_i+c_j}}{q^{|C_i\cap C_j|}}
\le q^{-\gamma}\cdot \sum_{C_i, C_j} p^{c_i+c_j} - q^{-\gamma}\cdot \sum_{C_i} p^{2c_i}
= 2(\zgp)^2 - 2\cdot \sum_{C_i} p^{2c_i}.
\end{align}

Finally, we bound $V_3$ as follows:
\[
V_3 
= \sum_{C_i\ne C_j, |C_i\cap C_j|>\gamma} p^{|C_i\cup C_j|}\left(\frac{p}{q}\right)^{|C_i\cap C_j|}
\le \sum_{C_i\ne C_j} p^{|C_i\cup C_j|}\left(\frac{p}{q}\right)^{\gamma}
= q^{-\gamma} \cdot x_G(p)\cdot p^{\gamma} 
\le 2\cdot x_G(p) \cdot \zgp.
\]
Since $p< \theta$, \Cref{lem:z-approx-u} gives $x_G(p) \le \frac{1}{\log n}\cdot \zgp$. Therefore,
\begin{align}\label{eq:v3}
    V_3 \le  2\cdot x_G(p) \cdot \zgp \le \frac{2}{\log n}\cdot (\zgp)^2.
\end{align}    

Putting the bounds on $V_1, V_2$ and $V_3$ given by \Cref{eq:v1,eq:v2,eq:v3} together, we get
\[
\frac{\E[z_H(p/q)^2]}{(\zgp)^2} 
\le \frac{V_1+V_2+V_3}{(\zgp)^2}  
= 2 + O\left(\frac{1}{\log n}\right).\qedhere
\]
\end{proof}
